#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AclKind {
    /// Base ACL v0.4.0 from `fhevm_host_bindings` (the baseline's bytecode; byte-identical to the
    /// v0.13.8 source compiled with the repo's forge profile).
    BaseBindings,
    /// Level 0 ACL v0.4.1 from `LIFECYCLE_L0_ACL_ARTIFACT`.
    Level0,
}

impl AclKind {
    fn slug(self) -> &'static str {
        match self {
            AclKind::BaseBindings => "base-bindings",
            AclKind::Level0 => "level0",
        }
    }
}

struct Artifact {
    bytecode: Bytes,
    deployed_bytecode: Bytes,
}

fn load_artifact(path: &Path) -> anyhow::Result<Artifact> {
    let json: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?,
    )?;
    let get = |key: &str| -> anyhow::Result<Bytes> {
        let hex = json[key]["object"]
            .as_str()
            .ok_or_else(|| anyhow!("{key}.object missing in {}", path.display()))?;
        Ok(Bytes::from_str(hex)?)
    };
    Ok(Artifact {
        bytecode: get("bytecode")?,
        deployed_bytecode: get("deployedBytecode")?,
    })
}

fn ensure_success(receipt: TransactionReceipt, what: &str) -> anyhow::Result<TransactionReceipt> {
    if receipt.status() {
        Ok(receipt)
    } else {
        Err(anyhow!("{what} reverted (tx {})", receipt.transaction_hash))
    }
}

async fn deploy_code(
    provider: &DynProvider,
    from: Address,
    code: Vec<u8>,
    what: &str,
) -> anyhow::Result<Address> {
    let tx = TransactionRequest::default()
        .with_from(from)
        .with_deploy_code(code);
    ensure_success(
        provider.send_transaction(tx).await?.get_receipt().await?,
        what,
    )?
    .contract_address
    .ok_or_else(|| anyhow!("{what}: no contract address"))
}

/// Same steps as `AnvilAcl::deploy` (Zama's `_deployACL` flow), with the ACL implementation taken
/// from a forge artifact instead of `fhevm_host_bindings`.
async fn deploy_acl_artifact(env: &Env, artifact: &Path, owner: Address) -> anyhow::Result<AnvilAcl> {
    let provider = ProviderBuilder::new()
        .connect_http(env.anvil_url.clone())
        .erased();
    let proxy_art = load_artifact(&env.sol_out.join("Proxy.sol/DeployableERC1967Proxy.json"))?;
    let executor_art = load_artifact(&env.sol_out.join("ExecutorStub.sol/ExecutorStub.json"))?;
    let dapp_art = load_artifact(&env.sol_out.join("DappStub.sol/DappStub.json"))?;
    let acl_art = load_artifact(artifact)?;

    let empty_impl = ensure_success(
        EmptyUUPSProxyACL::deploy_builder(&provider)
            .from(owner)
            .send()
            .await?
            .get_receipt()
            .await?,
        "EmptyUUPSProxyACL deploy",
    )?
    .contract_address
    .ok_or_else(|| anyhow!("no EmptyUUPSProxyACL address"))?;
    let init = EmptyUUPSProxyACL::initializeCall {
        initialOwner: owner,
    }
    .abi_encode();
    let mut proxy_code = proxy_art.bytecode.to_vec();
    proxy_code.extend((empty_impl, Bytes::from(init)).abi_encode_params());
    let acl = deploy_code(&provider, owner, proxy_code, "ERC1967Proxy deploy").await?;

    let acl_implementation = deploy_code(
        &provider,
        owner,
        acl_art.bytecode.to_vec(),
        "ACL implementation (artifact) deploy",
    )
    .await?;
    let reinit = ACL::initializeFromEmptyProxyCall {}.abi_encode();
    ensure_success(
        EmptyUUPSProxyACL::new(acl, &provider)
            .upgradeToAndCall(acl_implementation, reinit.into())
            .from(owner)
            .send()
            .await?
            .get_receipt()
            .await?,
        "upgradeToAndCall(ACL artifact, initializeFromEmptyProxy())",
    )?;

    let acl_instance = ACL::new(acl, &provider);
    let version = acl_instance.getVersion().call().await?;
    let acl_owner = acl_instance.owner().call().await?;
    ensure!(acl_owner == owner, "unexpected ACL owner {acl_owner}");
    let executor = acl_instance.getFHEVMExecutorAddress().call().await?;
    let _: serde_json::Value = provider
        .raw_request(
            "anvil_setCode".into(),
            (executor, executor_art.deployed_bytecode.clone()),
        )
        .await?;
    let dapp = deploy_code(&provider, owner, dapp_art.bytecode.to_vec(), "DappStub deploy").await?;
    info!(
        "Deployed real ACL ({version}) from artifact proxy={acl} impl={acl_implementation} owner={owner} \
        executor(stand-in)={executor} dapp C={dapp}"
    );
    Ok(AnvilAcl {
        provider,
        owner,
        acl,
        acl_implementation,
        executor,
        dapp,
        version,
    })
}

/// Zeroes the 32-byte words that hold `this` (the UUPS `__self` immutable), so the on-chain runtime code
/// can be compared with the compiler's runtime object, whose immutables are zero placeholders.
fn normalize_immutables(code: &[u8], this: Address) -> Vec<u8> {
    let mut word = [0u8; 32];
    word[12..].copy_from_slice(this.as_slice());
    let mut out = code.to_vec();
    let mut i = 0;
    while i + 32 <= out.len() {
        if out[i..i + 32] == word {
            out[i..i + 32].fill(0);
            i += 32;
        } else {
            i += 1;
        }
    }
    out
}

async fn deploy_acl(env: &Env, kind: AclKind, owner: Address) -> anyhow::Result<AnvilAcl> {
    let (acl, reference): (AnvilAcl, Bytes) = match kind {
        AclKind::BaseBindings => (
            AnvilAcl::deploy(env.anvil_url.clone(), &env.sol_out, owner).await?,
            ACL::DEPLOYED_BYTECODE.clone(),
        ),
        AclKind::Level0 => (
            deploy_acl_artifact(env, &env.l0_artifact, owner).await?,
            load_artifact(&env.l0_artifact)?.deployed_bytecode,
        ),
    };
    let onchain = acl.provider.get_code_at(acl.acl_implementation).await?;
    let matches = normalize_immutables(&onchain, acl.acl_implementation) == reference.to_vec();
    info!(
        "ACL-DEPLOY kind={} version=\"{}\" proxy={} impl={} runtime_bytes={} runtime_matches_reference={matches} \
        reference_keccak={}",
        kind.slug(),
        acl.version,
        acl.acl,
        acl.acl_implementation,
        onchain.len(),
        keccak256(&reference),
    );
    ensure!(matches, "deployed ACL runtime code does not match its reference");
    if kind == AclKind::Level0 {
        ensure!(acl.version == LEVEL0_VERSION, "unexpected Level 0 version {}", acl.version);
        let l0 = IAclLevel0::new(acl.acl, &acl.provider);
        let core = l0
            .supportsInterface(FixedBytes::<4>::new(DAL_CORE_INTERFACE_ID))
            .call()
            .await?;
        let location = l0.retirementStorageLocation().call().await?;
        info!("ACL-LEVEL0 supportsInterface(0x556d2088)={core} retirementStorageLocation={location}");
        ensure!(core && location == RETIREMENT_LOCATION, "Level 0 Core not declared");
    }
    Ok(acl)
}

fn make_handle(chain_id: u64) -> B256 {
    let mut h = rand_digest().0;
    h[21] = 0xff;
    h[22..30].copy_from_slice(&chain_id.to_be_bytes());
    h[30] = HANDLE_FHE_TYPE;
    h[31] = 0;
    B256::from(h)
}

/// Real grant and delegations: `h` persisted for C and U; U and V each delegate to D for C (1 day).
async fn setup_grants(acl: &AnvilAcl, a: &Accounts, handle: B256) -> anyhow::Result<()> {
    acl.grant(handle, a.u).await?;
    let expiration = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs() + 86_400;
    acl.delegate(a.u, a.d, acl.dapp, expiration).await?;
    acl.delegate(a.v, a.d, acl.dapp, expiration).await?;
    Ok(())
}

/// Direct (non-recorded) reads of the ACL state, logged as `ACL-STATE[tag]`.
async fn log_acl_state(
    acl: &AnvilAcl,
    a: &Accounts,
    handle: B256,
    kind: AclKind,
    tag: &str,
) -> anyhow::Result<()> {
    let view = acl.instance();
    let c = acl.dapp;
    info!(
        "ACL-STATE[{tag}] isAllowed(h,U)={} isAllowed(h,V)={} isAllowed(h,D)={} isAllowed(h,C)={} \
        isHandleDelegatedForUserDecryption(U,D,C,h)={} isHandleDelegatedForUserDecryption(V,D,C,h)={}",
        view.isAllowed(handle, a.u).call().await?,
        view.isAllowed(handle, a.v).call().await?,
        view.isAllowed(handle, a.d).call().await?,
        view.isAllowed(handle, c).call().await?,
        view.isHandleDelegatedForUserDecryption(a.u, a.d, c, handle).call().await?,
        view.isHandleDelegatedForUserDecryption(a.v, a.d, c, handle).call().await?,
    );
    if kind == AclKind::Level0 {
        let l0 = IAclLevel0::new(acl.acl, &acl.provider);
        info!(
            "ACL-STATE[{tag}] isAccountRetired(U)={} isAccountRetired(V)={} isAccountRetired(D)={} \
            isAccountRetired(C)={}",
            l0.isAccountRetired(a.u).call().await?,
            l0.isAccountRetired(a.v).call().await?,
            l0.isAccountRetired(a.d).call().await?,
            l0.isAccountRetired(c).call().await?,
        );
    }
    Ok(())
}

/// Retires `account` through the real `retireAccount()`: sent by the (unlocked) EOA itself, or, for the
/// dApp contract C, by C's own code (`DappStub.retireSelf`). Checks the `AccountRetired` event and
/// `isAccountRetired` (direct reads, not recorded).
async fn retire(acl: &AnvilAcl, account: Address, role: &str, case: &str) -> anyhow::Result<()> {
    let receipt = if account == acl.dapp {
        ensure_success(
            IDappRetire::new(acl.dapp, &acl.provider)
                .retireSelf(acl.acl)
                .from(acl.owner)
                .send()
                .await?
                .get_receipt()
                .await?,
            "DappStub.retireSelf",
        )?
    } else {
        ensure_success(
            IAclLevel0::new(acl.acl, &acl.provider)
                .retireAccount()
                .from(account)
                .send()
                .await?
                .get_receipt()
                .await?,
            "retireAccount",
        )?
    };
    let tx = receipt.transaction_hash;
    let raw: serde_json::Value = acl
        .provider
        .raw_request("eth_getTransactionReceipt".into(), (tx,))
        .await?;
    let topic0 = hex::encode_prefixed(keccak256("AccountRetired(address,address)"));
    let topic1 = hex::encode_prefixed(B256::left_padding_from(account.as_slice()));
    let topic2 = hex::encode_prefixed(B256::ZERO);
    let acl_addr = hex::encode_prefixed(acl.acl.as_slice());
    let mut event_ok = false;
    if let Some(logs) = raw["logs"].as_array() {
        for log in logs {
            let addr = log["address"].as_str().unwrap_or_default().to_lowercase();
            let topics: Vec<String> = log["topics"]
                .as_array()
                .map(|t| {
                    t.iter()
                        .map(|x| x.as_str().unwrap_or_default().to_lowercase())
                        .collect()
                })
                .unwrap_or_default();
            if addr == acl_addr && topics == vec![topic0.clone(), topic1.clone(), topic2.clone()] {
                event_ok = true;
            }
        }
    }
    let retired = IAclLevel0::new(acl.acl, &acl.provider)
        .isAccountRetired(account)
        .call()
        .await?;
    info!(
        "L0-RETIRE case={case} role={role} account={account} tx={tx} gas_used={} \
        account_retired_event={event_ok} isAccountRetired={retired}",
        receipt.gas_used
    );
    ensure!(event_ok && retired, "retirement of {account} not effective");
    Ok(())
}

