// ================================================================================================
// [Phase 5, P0.3] EIP-8298, simulated, on v0.13.8
// ================================================================================================
//
// At v0.13.8 the connector never checks the user's signature: the gateway does, with ECDSA only
// (gateway-contracts/contracts/Decryption.sol:923, `ECDSA.recover`). X is an anvil account that adopts regular code
// (NoErc1271's runtime; nothing on this line reads it, so only its kind matters). Env (set by run_p503.sh): P04_RUN,
// P04_ARTIFACTS.

fn p503_run() -> String {
    std::env::var("P04_RUN").unwrap_or_else(|_| "r1".to_string())
}

/// X retires as itself: impersonated on anvil (standing in for a call through its code).
async fn p503_retire_as_account(acl: &AnvilAcl, account: Address, case: &str) -> anyhow::Result<()> {
    let p = &acl.provider;
    let _: serde_json::Value = p.raw_request("anvil_impersonateAccount".into(), (account,)).await?;
    let res = retire(acl, account, "x-8298", case).await;
    let _: serde_json::Value = p.raw_request("anvil_stopImpersonatingAccount".into(), (account,)).await?;
    res
}

#[rstest]
#[timeout(Duration::from_secs(1800))]
#[tokio::test]
async fn p503_eip8298_unmodified() -> anyhow::Result<()> {
    let log_guard = init_tracing();
    let env = Env::load()?;
    let run = p503_run();
    let a = Accounts::load(&env).await?;
    let acl = deploy_acl(&env, AclKind::Level0, a.owner).await?;
    let handle = make_handle(env.chain_id);
    setup_grants(&acl, &a, handle).await?;
    // X: a sixth anvil account, granted h; it delegates to D while it is still an EOA.
    let x =ProviderBuilder::new().connect_http(env.anvil_url.clone()).get_accounts().await?[5];
    acl.grant(handle, x).await?;
    let artifacts = PathBuf::from(std::env::var("P04_ARTIFACTS")?);
    let no_art = load_artifact(&artifacts.join("NoErc1271.json"))?;
    let code = no_art.deployed_bytecode.clone();
    ensure!(!code.is_empty() && code[0] != 0xef, "NoErc1271 runtime is not regular code");

    let test_instance = TestInstanceBuilder::default()
        .with_tracing(Some(log_guard))
        .with_db(DbInstance::setup().await?)
        .build();
    let db = test_instance.db();
    let mut rh = RequestHarness::new(&env, &acl, AclKind::Level0, handle).await?;
    let cfg = RunCfg::harness();
    info!(
        "P503-CONFIG version={VERSION} tree=unmodified run={run} max_attempts={} fast_polling_ms={}",
        cfg.max_attempts,
        cfg.fast_polling.as_millis()
    );
    let mut mismatches: Vec<String> = Vec::new();
    let exp = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs() + 86_400;
    acl.delegate(x, a.d, acl.dapp, exp).await?;
    let _: serde_json::Value = acl.provider.raw_request("anvil_setCode".into(), (x, code.clone())).await?;
    ensure!(acl.provider.get_code_at(x).await? == code, "adopted code of X not in place");
    info!("P503-ACCOUNTS X={x} code_source=NoErc1271 code_len={} code_hash={}", code.len(), keccak256(&code));
    let rows: [(&str, bool, Outcome); 4] = [
        ("legacy-direct.x-8298", false, Outcome::Forwarded),
        ("legacy-delegated.d-for-x-8298", false, Outcome::Forwarded),
        ("legacy-direct.x-8298-retired", true, Outcome::Rejected),
        ("legacy-delegated.d-for-x-8298-retired", true, Outcome::Rejected),
    ];
    let mut retired = false;
    for (suffix, after, expect) in rows {
        if after && !retired {
            p503_retire_as_account(&acl, x, "p503").await?;
            retired = true;
        }
        let label = format!("p503.{run}.unmodified.{suffix}");
        let req = if suffix.starts_with("legacy-direct") {
            Req::direct(label.clone(), x, expect, "-")
        } else {
            Req::delegated(label.clone(), a.d, x, expect, "-")
        };
        let started = Instant::now();
        let res = rh.run(db, &req, &cfg).await;
        let wall_ms = started.elapsed().as_millis();
        match res {
            Ok(rr) => {
                info!(
                    "P503-RESULT label={label} version={VERSION} tree=unmodified expected={expect:?} observed={:?} \
                    kms_mock_hits={} error_counter={} error_code=- wall_ms={wall_ms}",
                    rr.observed,
                    rr.kms_hits,
                    rr.error_counter.map(|e| e.to_string()).unwrap_or_else(|| "-".into()),
                );
                let ok = match expect {
                    Outcome::Rejected => rr.observed == Outcome::Rejected && rr.kms_hits == 0,
                    Outcome::Forwarded => rr.observed == Outcome::Forwarded && rr.kms_hits >= 2,
                };
                if !ok {
                    mismatches.push(format!("{label}: expected {expect:?}, observed {:?}", rr.observed));
                }
            }
            Err(e) => {
                info!(
                    "P503-RESULT label={label} version={VERSION} tree=unmodified expected={expect:?} \
                    observed=HarnessError kms_mock_hits=- error_counter=- error_code=- wall_ms={wall_ms} error=\"{e:#}\""
                );
                mismatches.push(format!("{label}: harness error {e:#}"));
            }
        }
    }
    info!("P503-SUMMARY version={VERSION} tree=unmodified run={run} mismatches={}", mismatches.len());
    ensure!(mismatches.is_empty(), "P0.3 rows differ from the expectation: {mismatches:#?}");
    Ok(())
}
